import React from 'react';
import { Navigation, AlertCircle, CheckCircle2 } from 'lucide-react';

const ScheduleTab = ({ onNavigateToReports }) => {
  const routes = [
    { id: '101', time: '08:00', loc: 'SECTOR_04', type: 'PICKUP', status: 'done' },
    { id: '102', time: '10:30', loc: 'ZONE_DELTA', type: 'REPORT', urgency: 'high', status: 'pending' },
    { id: '103', time: '14:00', loc: 'CENTRAL_SQ', type: 'PICKUP', status: 'pending' },
  ];

  return (
    <div className="w-full max-w-lg animate-slide-up space-y-6">
      <h3 className="text-4xl font-black italic text-[#47510B] uppercase tracking-tighter px-4">Logistics.</h3>

      <div className="space-y-4">
        {routes.map((route) => (
          <div key={route.id} className={`p-6 rounded-[40px] border-4 border-[#47510B] shadow-[8px_8px_0_0_#47510B] flex justify-between items-center ${route.urgency === 'high' ? 'bg-[#FFB6A9]' : 'bg-white'}`}>
            <div className="flex-1">
              <span className="text-[10px] font-black opacity-30 uppercase">{route.time} // {route.type}</span>
              <h4 className="text-3xl font-black text-[#47510B] uppercase italic leading-none mt-1">{route.loc}</h4>

              {route.urgency === 'high' && (
                <button 
                  onClick={onNavigateToReports}
                  className="mt-3 flex items-center gap-2 text-[10px] font-black text-[#AB1717] uppercase animate-pulse"
                >
                  <AlertCircle size={14} /> View Citizen Report
                </button>
              )}
            </div>

            {route.status === 'done' ? (
              <CheckCircle2 size={40} className="text-[#CAD23C]" />
            ) : (
              <button 
                onClick={() => alert(`Opening GPS to ${route.loc}...`)}
                className="w-16 h-16 bg-[#47510B] text-[#CAD23C] rounded-2xl flex items-center justify-center hover:scale-110 transition-all shadow-lg"
              >
                <Navigation size={32} strokeWidth={3} />
              </button>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

export default ScheduleTab;
